//! Differential golden: assert the Rust port's ordinary byte-BPE encoding is
//! bit-identical to `ai-tokenizer`'s `claude` encoding across an adversarial
//! corpus. The fixture (`testdata/token-golden.json`) is generated by
//! `gen/gen-token-golden.ts` from the exact TS tokenizer the plugin uses.
//!
//! Asserting the full token-ID SEQUENCE (not just the count) proves the merges
//! are identical — a count-only check could pass on a wrong-but-same-length
//! encoding. `estimate_tokens` (the runtime API) is the ID count, so ID equality
//! implies count equality.

use mc_tokenizer::{encode_ordinary, estimate_tokens};
use serde::Deserialize;

#[derive(Deserialize)]
struct GoldenCase {
    label: String,
    text: String,
    ids: Vec<u32>,
}

fn load_golden() -> Vec<GoldenCase> {
    let raw = include_str!("../testdata/token-golden.json");
    serde_json::from_str(raw).expect("token-golden.json is malformed")
}

#[test]
fn encode_ordinary_matches_ai_tokenizer_ids() {
    let cases = load_golden();
    assert!(!cases.is_empty(), "golden corpus is empty");
    let mut failures = Vec::new();
    for c in &cases {
        let got = encode_ordinary(&c.text);
        if got != c.ids {
            failures.push(format!(
                "case '{}': text={:?}\n  expected {:?}\n  got      {:?}",
                c.label, c.text, c.ids, got
            ));
        }
        assert_eq!(
            estimate_tokens(&c.text),
            c.ids.len(),
            "estimate_tokens count mismatch for case '{}'",
            c.label
        );
    }
    assert!(
        failures.is_empty(),
        "token-ID mismatches vs ai-tokenizer (claude):\n{}",
        failures.join("\n")
    );
}

#[test]
fn deterministic_across_calls() {
    // The cache-stability invariant: the same text must always count identically
    // (a per-call variance would bust byte-identity on resume).
    let text = "Magic Context keeps a long session inside the context window.";
    let first = estimate_tokens(text);
    for _ in 0..3 {
        assert_eq!(estimate_tokens(text), first);
    }
}
